public struct EECircuitMNABench51:Sendable,Codable,Equatable {
 public var workspace=EEBenchWorkspace48(); public var protection=EEBenchProtection49(); public var time=0.0; public var last:EEBenchSolveResult51?; public var componentDamage:[String:Double]=[:]
 public init(){}
 public mutating func add(id:String,kind:EEBenchComponentKind48,terminals:[String],value:Double,enabled:Bool=true)->Bool{guard !id.isEmpty,terminals.count>=2,!workspace.components.contains(where:{$0.id==id}),terminals.allSatisfy({!workspace.terminalExists($0)}) else{return false};workspace.components.append(.init(id:id,kind:kind,terminals:terminals,value:value,enabled:enabled));return true}
 public mutating func removeComponent(_ id:String){let ts=Set(workspace.components.first(where:{$0.id==id})?.terminals ?? []);workspace.components.removeAll{$0.id==id};workspace.wires.removeAll{ts.contains($0.from)||ts.contains($0.to)}}
 public mutating func setEnabled(_ id:String,_ enabled:Bool){if let i=workspace.components.firstIndex(where:{$0.id==id}){workspace.components[i].enabled=enabled}}
 public mutating func wire(_ a:String,_ b:String,resistanceOhm:Double=0.02)->Bool{guard workspace.terminalExists(a),workspace.terminalExists(b),a != b,resistanceOhm>0 else{return false};workspace.wire(a,b,resistanceOhm:resistanceOhm);return true}
 private func compiled()->(Circuit,[String:Int],[String])?{
  let all=workspace.components.flatMap{$0.terminals}; guard Set(all).count==all.count else{return nil}; let wired=Set(workspace.wires.filter{$0.healthy}.flatMap{[$0.from,$0.to]}); let supplyTerms=Set(workspace.components.filter{$0.kind == .supply && $0.enabled}.flatMap{$0.terminals}); let included=workspace.components.filter{c in c.kind == .supply || c.terminals.contains(where:{wired.contains($0)})}.flatMap{$0.terminals}; let terminals=Array(Set(included).union(supplyTerms)).sorted()
  let ground = workspace.components.first(where:{$0.kind == .supply})?.terminals.dropFirst().first ?? terminals.first
  guard let g=ground else{return nil}; var map:[String:Int]=[g:0];var next=1;for t in terminals where map[t]==nil{map[t]=next;next += 1}
  var rs:[Resistor]=[];var vs:[VoltageSource]=[]
  for w in workspace.wires where w.healthy {guard let a=map[w.from],let b=map[w.to] else{continue};rs.append(.init(a:a,b:b,resistance:max(1e-6,w.resistanceOhm)))}
  for c in workspace.components where c.enabled && c.terminals.count>=2 {guard let a=map[c.terminals[0]],let b=map[c.terminals[1]] else{continue};switch c.kind {
   case .supply: vs.append(.init(positive:a,negative:b,volts:c.value))
   case .resistor: rs.append(.init(a:a,b:b,resistance:max(1e-6,c.value)))
   case .lamp: let r = c.value > 0 ? max(0.01,24*24/c.value) : 1e9;rs.append(.init(a:a,b:b,resistance:r))
   case .relayCoil: rs.append(.init(a:a,b:b,resistance:max(1,c.value)))
   case .motor: rs.append(.init(a:a,b:b,resistance:max(0.05,c.value)))
   case .transmitter,.analogInput: rs.append(.init(a:a,b:b,resistance:max(50,c.value)))
   case .canTermination: rs.append(.init(a:a,b:b,resistance:max(1,c.value)))
   case .switchDevice,.relayContact: rs.append(.init(a:a,b:b,resistance:0.001))
   case .capacitor,.diode,.plcOutput,.vfd,.networkNode: break
  }}
  return(.init(nodeCount:next,resistors:rs,voltageSources:vs),map,terminals)
 }
 public mutating func solve(seconds:Double=0.01)->EEBenchSolveResult51 {time += max(0,seconds);guard workspace.energized else{let r=EEBenchSolveResult51(state:.deenergized,nodeVoltages:[],sourceCurrentsA:[],residual:0,islands:[],message:"Bench is de-energized");last=r;return r};guard let (c,map,terminals)=compiled() else{let r=EEBenchSolveResult51(state:.invalidTopology,nodeVoltages:[],sourceCurrentsA:[],residual:0,islands:[],message:"Duplicate or invalid terminal topology");last=r;return r};do{let snap=try ReferenceDCSolver().solve(c);let volts=terminals.compactMap{t -> EEBenchNodeVoltage51? in guard let n=map[t],n<snap.nodeVoltages.count else{return nil};return .init(id:t,volts:snap.nodeVoltages[n])};let inv=Dictionary(uniqueKeysWithValues:map.map{($0.value,$0.key)});let islands=IslandDetector.detect(c).map{$0.nodes.compactMap{inv[$0]}};let maxI=snap.voltageSourceCurrents.map{abs($0)}.max() ?? 0;protection.apply(currentA:maxI,seconds:seconds);if maxI>10{componentDamage["SUPPLY",default:0]=min(1,componentDamage["SUPPLY",default:0]+seconds*0.05)};if protection.state != .healthy{workspace.energized=false};let r=EEBenchSolveResult51(state:.solved,nodeVoltages:volts,sourceCurrentsA:snap.voltageSourceCurrents,residual:snap.residual,islands:islands,message:"CircuitMNA converged");last=r;return r}catch{let r=EEBenchSolveResult51(state:.singular,nodeVoltages:[],sourceCurrentsA:[],residual:1e300,islands:[],message:"Floating/open topology: \(error)");last=r;return r}}
 public mutating func energize(_ on:Bool=true){workspace.energized=on}
 public mutating func measure(red:String,black:String)->Double?{guard let r=last?.voltage(red),let b=last?.voltage(black) else{return nil};return r-b}
}

public struct EEGoldenThreadAudit51:Sendable,Codable,Equatable { public var total:Int; public var withPhysical:Int; public var withEngineering:Int; public var withHistorian:Int; public var orphanIDs:[String]; public var duplicateKeys:[String]; public var coverage:Double }
public struct EERegistryCompleteGoldenThread51:Sendable,Codable,Equatable {
 public var identities:[EEUniversalIdentity]
 public init(base:EERegistryGoldenThread49,timeline:EEForensicTimelineRev46){var map:[String:EEUniversalIdentity]=[:];func key(_ i:EEUniversalIdentity)->String{"\(i.world?.rawValue ?? "common")|\(i.id)"};for i in base.identities{map[key(i)]=i}
  for world in [EEIndustrialWorld.naturalGas,.coalMining] {for s in timeline.snapshots(for:world){for c in s.channels{let k="\(world.rawValue)|\(c.sourceIdentity)";var i=map[k] ?? .init(id:c.sourceIdentity,world:world,bindings:[]);if !i.bindings.contains(where:{$0.surface == .historian && $0.reference==c.id}){i.bindings.append(.init(.historian,c.id))};map[k]=i}}}
  identities=map.values.map{item in var i=item;if !i.bindings.contains(where:{$0.surface == .physical}){i.bindings.append(.init(.physical,"UNMAPPED:\(i.id)"))};return i}.sorted{($0.world?.rawValue ?? "")+"|"+$0.id < ($1.world?.rawValue ?? "")+"|"+$1.id}
 }
 public func identity(_ id:String,world:EEIndustrialWorld)->EEUniversalIdentity?{identities.first{$0.id==id && $0.world==world}}
 public func related(_ q:String)->[EEUniversalIdentity]{identities.filter{q.isEmpty || $0.id.localizedCaseInsensitiveContains(q)||$0.bindings.contains{$0.reference.localizedCaseInsensitiveContains(q)}}}
 public var audit:EEGoldenThreadAudit51 {var seen:Set<String>=[];var dup:[String]=[];var physical=0,engineering=0,hist=0;var orphan:[String]=[];for i in identities{let k="\(i.world?.rawValue ?? "common")|\(i.id)";if !seen.insert(k).inserted{dup.append(k)};let p=i.bindings.contains{$0.surface == .physical && !$0.reference.hasPrefix("UNMAPPED:")};let e=i.bindings.contains{[EEEngineeringSurface.oneLine,.elementary,.loopSheet,.pAndID,.plc,.hmi,.network].contains($0.surface)};let h=i.bindings.contains{$0.surface == .historian};if p{physical+=1};if e{engineering+=1};if h{hist+=1};if !p && !e && !h{orphan.append(i.id)}};let total=max(1,identities.count);return .init(total:identities.count,withPhysical:physical,withEngineering:engineering,withHistorian:hist,orphanIDs:orphan,duplicateKeys:dup,coverage:Double(identities.count-orphan.count)/Double(total))}
}

