 public var gas:[EEForensicFrame51]=[];public var coal:[EEForensicFrame51]=[];public var capacity=14_400;public init(){}
 public mutating func append(_ f:EEForensicFrame51){if f.world == .naturalGas{gas.append(f);if gas.count>capacity{gas.removeFirst(gas.count-capacity)}}else{coal.append(f);if coal.count>capacity{coal.removeFirst(coal.count-capacity)}}}
