}

public struct EERev51TechnicalCeiling:Sendable,Codable,Equatable {
 public var base=EERev50PhysicalizedForensics();public var bench=EECircuitMNABench51();public var replay=EESynchronizedReplay51();public var scanCounter:[EEIndustrialWorld:Int]=[.naturalGas:0,.coalMining:0]
