  let network:[EENetworkReplay51];let thermal:[EEThermalReplay51];let vibration:[EEVibrationReplay51]
  if world == .naturalGas {let g=base.base.base.base.base.gas;network=[.init(node:"PLC-GAS",latencyMS:2.0,packetLoss:0,stale:false),.init(node:"VFD-2",latencyMS:2.5,packetLoss:0,stale:false)];thermal=[.init(asset:"COMP-2",temperatureC:g.rev39.base.unit.bearingTempC,riseC:g.rev39.base.unit.bearingTempC-25)];vibration=[.init(asset:"COMP-2",overall:g.rev39.base.unit.vibration,orders:[1:g.rev39.base.unit.vibration,2:g.rev39.base.unit.vibration*0.42])];if g.vfd.dcRippleV>30{soe.append(.init(id:"SOE-GAS-RIPPLE-\(s.time)",time:s.time,source:"VFD-2",text:"Elevated DC bus ripple",priority:2))}
  } else {let c=base.base.base.base.base.coal;let belt=c.rev43.belts[.northRidge];network=[.init(node:"PLC-COAL",latencyMS:3.0,packetLoss:0,stale:false),.init(node:"TLO-RIO",latencyMS:4.0,packetLoss:0,stale:false)];thermal=[.init(asset:"CV-NR-OL",temperatureC:belt?.segments.map{$0.idlerTempC}.max() ?? 25,riseC:max(0,(belt?.segments.map{$0.idlerTempC}.max() ?? 25)-25)),.init(asset:"CENT-101",temperatureC:c.centrifuge.bearingTempC,riseC:c.centrifuge.bearingTempC-25)];vibration=[.init(asset:"CENT-101",overall:c.centrifuge.vibrationMMPS,orders:[1:c.centrifuge.vibrationMMPS,2:c.centrifuge.vibrationMMPS*0.35]),.init(asset:"LW-NR",overall:c.rev43.longwalls[.northRidge]?.shearer.vibrationMMPS ?? 0,orders:[1:c.rev43.longwalls[.northRidge]?.shearer.vibrationMMPS ?? 0])];if (belt?.segments.map{$0.idlerTempC}.max() ?? 0)>80{soe.append(.init(id:"SOE-COAL-IDLER-\(s.time)",time:s.time,source:"CV-NR-OL",text:"High idler temperature",priority:1))}}
  replay.append(.init(id:"F51-\(world.rawValue)-\(s.time)",world:world,time:s.time,process:values,plc:plc,soe:soe,network:network,thermal:thermal,vibration:vibration,evidenceIDs:evidence))
 }
