 public mutating func rcStep(sourceV:Double=10,resistance:Double=1000,capacitance:Double=1e-6,dt:Double=0.0001,steps:Int=100)->EETransientTrace53{var cap = capacitors["C1"] ?? makeTransientCapacitor53(capacitance); trace = .init();for k in 0..<max(1,steps){let stamp=cap.stamp(dt:dt,a:1,b:0);let c=Circuit(nodeCount:2,resistors:[.init(a:1,b:0,resistance:resistance),stamp.0],currentSources:[stamp.1],voltageSources:[.init(positive:1,negative:0,volts:sourceV)]);if let s=try? ReferenceDCSolver().solve(c){let v=s.nodeVoltages[1];cap.commit(voltage:v);trace.times.append(Double(k+1)*dt);trace.voltages["C1",default:[]].append(v);trace.convergedSteps += 1}};capacitors["C1"]=cap;return trace}
 public func diodeOperatingPoint(sourceV:Double=5,seriesOhms:Double=1000)->(voltage:Double,iterations:Int,converged:Bool){DiodeNewtonSolver().solve(sourceVolts:sourceV,seriesOhms:seriesOhms)}
}
