public struct EEAnalysisLab53:Sendable,Codable,Equatable {
 public var results:[EEAnalysisResult53]=[];public init(){}
 public mutating func dcSweep(resistance:Double=1000,start:Double=0,stop:Double=24,points:Int=25)->EEAnalysisResult53{let n=max(2,points);let x=(0..<n).map{start+(stop-start)*Double($0)/Double(n-1)};let y=x.map{$0/max(resistance,1e-9)};let r=EEAnalysisResult53(mode:.dcSweep,x:x,y:y,summary:"DC source sweep through \(resistance) Ω");results.append(r);return r}
 public mutating func acSweepRC(resistance:Double=1000,capacitance:Double=1e-6,startHz:Double=1,stopHz:Double=100_000,points:Int=81)->EEAnalysisResult53{let n=max(2,points);let a=log10(startHz),b=log10(stopHz);let x=(0..<n).map{pow(10,a+(b-a)*Double($0)/Double(n-1))};let y=x.map{f in let w=2*Double.pi*f;return 1/sqrt(1+pow(w*resistance*capacitance,2))};let r=EEAnalysisResult53(mode:.acSweep,x:x,y:y,summary:"RC low-pass magnitude sweep");results.append(r);return r}
 public mutating func monteCarloResistance(nominal:Double=1000,tolerance:Double=0.05,samples:Int=200,seed:UInt64=53)->EEAnalysisResult53{var s=seed;func rnd()->Double{s = 6364136223846793005 &* s &+ 1442695040888963407;return Double(s>>11)/Double(UInt64.max>>11)};let x=(0..<max(1,samples)).map{Double($0)};let y=x.map{_ in nominal*(1+tolerance*(2*rnd()-1))};let r=EEAnalysisResult53(mode:.monteCarlo,x:x,y:y,summary:"Deterministic tolerance Monte Carlo");results.append(r);return r}
}
