public struct EERelayMechanics53:Sendable,Codable,Equatable {public var coilVolts=0.0;public var ratedVolts=24.0;public var armature=0.0;public var contactResistance=0.02;public var cycles=0;public var welded=false;public init(){};public mutating func step(dt:Double){let target=coilVolts >= 0.7*ratedVolts ? 1.0:0.0;armature += (target-armature)*min(1,dt*30);if armature>0.95 && target>0.5{cycles += 1};contactResistance=min(2,0.02+Double(cycles)*1e-7);if welded{armature=max(armature,0.99)}};public var closed:Bool{armature>0.85||welded}}
