public struct EEAdaptiveTransient54:Sendable,Codable,Equatable {
 public var minDT=1e-7, maxDT=2e-3, tolerance=1e-4;public var trace:[EEAdaptiveStep54]=[];public init(){}
 public mutating func rc(source:EEFunctionGenerator53=EEFunctionGenerator53(),r:Double=1000,c:Double=1e-6,duration:Double=0.01)->[EEAdaptiveStep54]{trace=[];var t=0.0,v=0.0,dt=min(1e-4,maxDT);while t<duration{let h=min(dt,duration-t);let vin=source.value(at:t+h);let next=(v+h*vin/(r*c))/(1+h/(r*c));let half=h/2;let mid=(v+half*source.value(at:t+half)/(r*c))/(1+half/(r*c));let fine=(mid+half*vin/(r*c))/(1+half/(r*c));let err=abs(fine-next);if err>tolerance && h>minDT*1.01{dt=max(minDT,h/2);continue};v=fine;t+=h;trace.append(.init(time:t,dt:h,value:v,iterations:1));if err<tolerance*0.1{dt=min(maxDT,h*1.6)}};return trace}
}
public struct EENonlinearModels54:Sendable,Codable,Equatable {public init(){};public func bjtCollector(baseV:Double,beta:Double=100)->Double{let ib=max(0,(baseV-0.7)/10_000);return min(0.2,beta*ib)};public func mosfetDrain(gateV:Double,threshold:Double=2.5,k:Double=0.08)->Double{let x=max(0,gateV-threshold);return k*x*x};public func opAmp(vPlus:Double,vMinus:Double,gain:Double=100_000,rails:ClosedRange<Double> = -12...12)->Double{min(rails.upperBound,max(rails.lowerBound,(vPlus-vMinus)*gain))}}
