public struct EEScopeEngine54:Sendable,Codable,Equatable {public var level=0.0;public var rising=true;public var mode:EETriggerMode54 = .auto;public var cursorA=0,cursorB=0;public init(){};public func triggerIndex(_ x:[Double])->Int?{guard x.count>1 else{return nil};return (1..<x.count).first{rising ? (x[$0-1]<level && x[$0]>=level):(x[$0-1]>level && x[$0]<=level)}};public func measure(_ x:[Double],sampleRate:Double)->EEScopeMeasurement54{guard !x.isEmpty else{return .init(minimum:0,maximum:0,mean:0,rms:0,frequencyHz:nil)};let mean=x.reduce(0,+)/Double(x.count);let rms=sqrt(x.map{$0*$0}.reduce(0,+)/Double(x.count));var crossings=0;for i in 1..<x.count where x[i-1]<mean && x[i]>=mean{crossings += 1};let f=crossings>1 ? Double(crossings-1)*sampleRate/Double(x.count):nil;return .init(minimum:x.min()!,maximum:x.max()!,mean:mean,rms:rms,frequencyHz:f)};public func cursorDelta(sampleRate:Double)->Double{Double(abs(cursorB-cursorA))/sampleRate};public func fftMagnitude(_ x:[Double],bins:Int=32)->[Double]{guard !x.isEmpty else{return []};let n=x.count;return (0..<min(bins,n/2)).map{k in var re=0.0,im=0.0;for i in 0..<n{let a=2*Double.pi*Double(k*i)/Double(n);re += x[i]*cos(a);im -= x[i]*sin(a)};return sqrt(re*re+im*im)/Double(n)}}}
