public struct EENonlinearConvergence55: Sendable,Codable,Equatable { public var converged:Bool; public var iterations:Int; public var residual:Double; public var limitedSteps:Int }
public struct EENonlinearResult55: Sendable,Codable,Equatable { public var voltage:Double; public var current:Double; public var report:EENonlinearConvergence55 }
public struct EENonlinearMNA55: Sendable,Codable,Equatable {
 public var maxIterations=80; public var voltageTolerance=1e-9; public var residualTolerance=1e-10; public var maxStep=0.35; public init(){}
 private func solveNode(sourceV:Double,sourceR:Double,initial:Double,current:(Double)->Double,conductance:(Double)->Double)->EENonlinearResult55 { var v=initial;var limited=0;var res=Double.infinity;for i in 1...maxIterations{let f=(v-sourceV)/sourceR+current(v);let g=1/sourceR+conductance(v);res=abs(f);if res<residualTolerance{return .init(voltage:v,current:(sourceV-v)/sourceR,report:.init(converged:true,iterations:i,residual:res,limitedSteps:limited))};var dv = -f/max(abs(g),1e-15);if abs(dv)>maxStep{dv=maxStep*(dv<0 ? -1:1);limited += 1};v += dv;if abs(dv)<voltageTolerance && res<residualTolerance*10{return .init(voltage:v,current:(sourceV-v)/sourceR,report:.init(converged:true,iterations:i,residual:res,limitedSteps:limited))}};return .init(voltage:v,current:(sourceV-v)/sourceR,report:.init(converged:false,iterations:maxIterations,residual:res,limitedSteps:limited)) }
 public func diode(sourceV:Double=5,sourceR:Double=1000,isat:Double=1e-12,n:Double=1)->EENonlinearResult55 {let vt=0.025852*n;return solveNode(sourceV:sourceV,sourceR:sourceR,initial:min(0.7,sourceV),current:{v in isat*(exp(min(v/vt,40))-1)},conductance:{v in isat/vt*exp(min(v/vt,40))})}
 public func mosfetDiodeConnected(sourceV:Double=5,sourceR:Double=1000,vth:Double=2,k:Double=0.002)->EENonlinearResult55 {solveNode(sourceV:sourceV,sourceR:sourceR,initial:min(sourceV,vth+0.5),current:{v in let x=max(0,v-vth);return 0.5*k*x*x},conductance:{v in k*max(0,v-vth)})}
 public func bjtDiodeConnected(sourceV:Double=5,sourceR:Double=1000,isat:Double=1e-15,beta:Double=100)->EENonlinearResult55 {let vt=0.025852;return solveNode(sourceV:sourceV,sourceR:sourceR,initial:0.7,current:{v in (beta+1)*isat*(exp(min(v/vt,40))-1)},conductance:{v in (beta+1)*isat/vt*exp(min(v/vt,40))})}
 public func opAmpFollower(input:Double,positiveRail:Double=12,negativeRail:Double = -12,openLoopGain:Double=100_000)->EENonlinearResult55 {let out=min(positiveRail,max(negativeRail,input*openLoopGain/(1+openLoopGain)));return .init(voltage:out,current:0,report:.init(converged:true,iterations:1,residual:abs(out-input),limitedSteps:0))}
}
