public struct EEProfessionalScope55:Sendable,Codable,Equatable {public var sampleRate=100_000.0;public var pretriggerFraction=0.25;public var holdoff=0.0;public var coupling:EEScopeCoupling55 = .dc;public var attenuation=1.0;public var bandwidthHz=20_000_000.0;public var acquisition:EEScopeAcquire55 = .sample;public var window:EEFFTWindow55 = .hann;public var cursorA=0;public var cursorB=0;public init(){};public func condition(_ x:[Double])->[Double]{guard !x.isEmpty else{return []};if coupling == .ground{return Array(repeating:0,count:x.count)};let mean=x.reduce(0,+)/Double(x.count);let base=coupling == .ac ? x.map{$0-mean}:x;return base.map{$0*attenuation}};public func interpolate(_ x:[Double],at index:Double)->Double{guard !x.isEmpty else{return 0};let a=max(0,min(x.count-1,Int(floor(index)))),b=max(0,min(x.count-1,a+1)),f=index-Double(a);return x[a]*(1-f)+x[b]*f};public func windowed(_ x:[Double])->[Double]{let n=max(1,x.count-1);return x.enumerated().map{i,v in let q=2*Double.pi*Double(i)/Double(n);let w:Double;switch window{case .rectangular:w=1;case .hann:w=0.5-0.5*cos(q);case .hamming:w=0.54-0.46*cos(q);case .blackman:w=0.42-0.5*cos(q)+0.08*cos(2*q)};return v*w}};public func xy(_ x:[Double],_ y:[Double])->[(Double,Double)]{Array(zip(x,y))};public func math(_ a:[Double],_ b:[Double],subtract:Bool=false)->[Double]{zip(a,b).map{subtract ? $0-$1:$0+$1}}}
public struct EEElectromechanical55:Sendable,Codable,Equatable {public var ratedV=24.0,coilR=240.0,armature=0.0,velocity=0.0,springK=18.0,residual=0.02,coilTempC=25.0,contactR=0.02,erosion=0.0;public var welded=false;public var chatterCount=0;public init(){};public mutating func step(voltage:Double,loadCurrent:Double=0,dt:Double=0.001){let hotR=coilR*(1+0.00393*(coilTempC-20));let i=voltage/max(hotR,1e-9);let magnetic=5000*i*i+residual;let spring=springK*armature;let accel=(magnetic-spring-1.8*velocity);velocity += accel*dt;armature=min(1,max(0,armature+velocity*dt));coilTempC += ((i*i*hotR)*0.02-(coilTempC-25)*0.08)*dt;if armature>0.82 && armature<0.9{chatterCount += 1};if closed{erosion += abs(loadCurrent)*dt*1e-5;contactR=0.02+erosion};if loadCurrent>40 && closed{welded=true}};public var closed:Bool{welded || armature>0.86}}
