public struct EEGoldenCircuitCorpus55:Sendable,Codable,Equatable {public var cases:[EEGoldenCase55]=[];public init(){};public mutating func run(){cases=[];cases.append(.init(id:"DC-divider",expected:5,actual:10*1000/(1000+1000),tolerance:1e-12,category:"DC"));let diode=EENonlinearMNA55().diode();cases.append(.init(id:"Diode-1k-5V",expected:0.574147,actual:diode.voltage,tolerance:0.015,category:"nonlinear"));var d=EEDynamicDeviceCompiler55();d.add(.init(id:"R",kind:.resistor,value:1000));d.add(.init(id:"C",kind:.capacitor,value:1e-6));var v=0.0;for _ in 0..<1000{v=d.stepSeries(sourceV:10,dt:1e-6)};cases.append(.init(id:"RC-one-tau",expected:10*(1-exp(-1)),actual:v,tolerance:0.01,category:"transient"));var l=EEDynamicDeviceCompiler55();l.add(.init(id:"R",kind:.resistor,value:10));l.add(.init(id:"L",kind:.inductor,value:0.1));var vr=0.0;for _ in 0..<1000{vr=l.stepSeries(sourceV:10,dt:1e-5)};cases.append(.init(id:"RL-one-tau",expected:10*(1-exp(-1)),actual:vr,tolerance:0.01,category:"transient"))};public var passed:Bool{!cases.isEmpty && cases.allSatisfy{$0.passed}}}
